// Split one shard's rows into two by hash range at boundary `mid`.
// Every row must land on exactly one of the two shards (no row lost, no row duplicated).
function split(rows, mid) {
  const shard0 = rows.filter(r => r.hash < mid);
  const shard1 = rows.filter(r => r.hash > mid); // BUG: rows where hash === mid land nowhere
  return { shard0, shard1 };
}

