// shards: array of shard clients
async function topCustomersBySpend(shards, limit) {
  const perShard = await Promise.all(
    shards.map(s =>
      s.query(
        'SELECT customer_id, SUM(amount) AS spend FROM orders ' +
        'GROUP BY customer_id ORDER BY spend DESC LIMIT ' + limit
      )
    )
  );
  // merge: concat all shard results, sort, take top `limit`
  const merged = [].concat(...perShard);
  merged.sort((a, b) => b.spend - a.spend);
  return merged.slice(0, limit);
}

async function countOrders(shards) {
  const counts = await Promise.all(
    shards.map(s => s.query('SELECT COUNT(*) AS c FROM orders'))
  );
  return counts[0].c;
}
